    (v_id, $q$Core Section$q$, $q$Core Section (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Sand Density$q$, $q$Sand Density (kg/m³)$q$, $q$number$q$, $q$kg/m³$q$, NULL, NULL, NULL, NULL, 5, true),
